from text_adventure_games import games, things, actions, blocks
from text_adventure_games.npc import make_hybrid_behavior


class BlackboardJungle(games.Game):
    def __init__(self, start_at, player, characters=None, custom_actions=None):
        super().__init__(start_at, player, characters, custom_actions)

    def is_won(self) -> bool:
        if self.game_over:
            return True
        for name, character in self.characters.items():
            if character.get_property("homework_submitted") == True:
                msg = '"Well, well. Color me impressed!" Your scheme seems to have worked out, allowing you to survive one more day in the Blackboard Jungle. THE END.'.format(
                    name=character.name.title()
                )
                self.game_over = True
                self.game_over_description = msg
                self.parser.ok(msg)
                return True
        return False

    # ----------------------------- Glasses --------------------------------
    # The cat-eye glasses (page 78): "The player cannot see room contents,
    # exits or examine objects while wearing the glasses." We model that by
    # short-circuiting look/examine when the glasses are in the worn slot,
    # and by returning a blurry stand-in from describe() so the post-move
    # auto-narration is also obscured.

    _BLUR_TEXT = (
        "Everything is blurry and indistinct. You can barely see the "
        "shapes in front of you. Maybe TAKE OFF GLASSES."
    )

    def _glasses_on(self) -> bool:
        return "glasses" in self.player.worn

    def describe(self) -> str:
        if self._glasses_on():
            return self._BLUR_TEXT
        return super().describe()

    def do_command(self, command: str) -> bool:
        cmd = (command or "").strip().lower()
        # Block look/examine while wearing the glasses. We intercept before
        # the parser so the engine's normal narration never runs.
        if self._glasses_on() and (
            cmd in ("look", "l")
            or cmd.startswith("look ")
            or cmd.startswith("l ")
            or cmd.startswith("examine ")
            or cmd.startswith("x ")
        ):
            self.parser.ok(self._BLUR_TEXT)
            # Charge the turn -- the player did look at something.
            self.end_turn()
            return True

        # Detect entry into the Library. PDF page 82: "If the player
        # character never picked up the glasses or is sent to the Library
        # a second time: You spend the next four hours staring at the
        # wall. THE END."
        before = self.player.location
        success = super().do_command(command)
        after = self.player.location
        if success and before is not after and after is not None:
            if after.name == "Library":
                self.player.set_property(
                    "library_visits",
                    int(self.player.get_property("library_visits") or 0) + 1,
                )
                has_glasses = (
                    "glasses" in self.player.inventory or "glasses" in self.player.worn
                )
                visits = int(self.player.get_property("library_visits") or 0)
                if not has_glasses or visits > 1:
                    ending = (
                        "You spend the next four hours staring at the " "wall. THE END."
                    )
                    self.parser.ok(ending)
                    self.game_over = True
                    self.game_over_description = ending
        return success


