class Wear_Glasses(actions.Action):
    """Actually put the glasses on -- moves them into the player's worn
    slot. The codegen had emitted a flavor-only stub that printed the
    blurry text without changing world state, so neither the engine's
    TAKE OFF nor the BlackboardJungle.describe()/do_command blur hook
    (which both read ``"glasses" in player.worn``) could observe the
    glasses as worn."""

    ACTION_NAME = "wear glasses"
    ACTION_DESCRIPTION = "Put on the cat-eye glasses"
    ACTION_ALIASES = []
    PLAYER_CUSTOM = True

    def __init__(self, game, command, actor=None):
        super().__init__(game, actor=actor)
        self.character = self.acting_character(command)
        self.glasses = self.parser.match_item("glasses", self.character.inventory)

    def check_preconditions(self) -> bool:
        if self.glasses is None:
            self.parser.fail("You don't have the glasses to put on.")
            return False
        if self.character.is_worn(self.glasses):
            self.parser.fail("You're already wearing the glasses.")
            return False
        return True

    def apply_effects(self):
        self.character.wear(self.glasses)
        self.parser.ok(
            "You put on the cat-eye glasses. Everything is blurry and " "indistinct."
        )


