def build_game(llm_client=None) -> BlackboardJungle:
    gymnasium = things.Location(
        "Gymnasium",
        "You are in the gym. It's currently devoid of sweaty athletes and cheering fans. You smell a locker room to the south. The exit is to the east. You see an eyeglasses case on the ground.",
    )
    locker_room = things.Location(
        "Locker Room",
        "You are in one of Parsely High's locker rooms. There is a janitor's cart here.",
    )
    hallway_west = things.Location(
        "Hallway West",
        "You're at the western end of a long hallway. Someone appears to have had tummy troubles; there's a puddle of sick on the floor. There's a classroom door here. The gym is to the west.",
    )
    hallway_west.set_property("puddle_cleaned", False)
    hallway_east = things.Location(
        "Hallway East",
        "You stand at the eastern end of a long hallway. There are rows of lockers on either side of you. You see the door leading to the library.",
    )
    library = things.Location(
        "Library",
        "You're in the library, where you usually spend much of your time... after school, in detention. There is a study cubby here. There is a book here. Ms. Green, the librarian, is here.",
    )
    classroom = things.Location(
        "Classroom",
        'You step into the classroom, and your English teacher, Mr. Bushel, clears his throat. "Late as usual. I sincerely hope you remembered your homework." He holds out a hand.',
    )

    gymnasium.add_connection("south", locker_room, "You head into the locker room.")
    gymnasium.add_connection(
        "east", hallway_west, "You step into the western end of the hallway."
    )
    hallway_west.add_connection(
        "east", hallway_east, "You walk to the eastern end of the hallway."
    )
    hallway_east.add_connection("east", library, "You enter the library.")

    case = things.Item(
        "case", "an eyeglasses case", "Inside the case are a pair of cat-eye glasses."
    )
    case.set_property("is_openable", True)
    case.add_command_hint("examine case")
    case.add_command_hint("open case")
    gymnasium.add_item(case)
    glasses = things.Item(
        "glasses",
        "a pair of bedazzled cat-eye glasses",
        "The bedazzled cat-eye glasses aren't really your style.",
    )
    glasses.set_property("wearable", True)
    glasses.set_property("is_worn", False)
    glasses.add_command_hint("wear glasses")
    glasses.add_command_hint("take glasses")
    glasses.add_command_hint("give glasses to librarian")
    gymnasium.add_item(glasses)
    cart = things.Item(
        "cart",
        "a janitor's cart, more or less a trash can on wheels",
        "The janitor's cart is more or less a trash can on wheels. A bucket of pink sawdust and a broom hang from the cart.",
    )
    cart.set_property("gettable", False)
    cart.add_command_hint("examine cart")
    cart.add_command_hint("push cart")
    locker_room.add_item(cart)
    # EXAMINE TRASH CAN on page 79 -- the can is part of the cart, but
    # examining it specifically discovers the freshman hiding inside.
    trash_can = things.Item(
        "trash can",
        "the cart's trash can",
        "You peer inside the trash can and find a freshman cowering at " "the bottom.",
    )
    trash_can.set_property("gettable", False)
    trash_can.add_command_hint("examine trash can")
    trash_can.add_command_hint("talk to freshman")
    locker_room.add_item(trash_can)
    bucket = things.Item(
        "bucket",
        "a bucket of pink sawdust",
        "A bucket of pink sawdust, the janitor's best friend.",
    )
    bucket.add_command_hint("get bucket")
    bucket.add_command_hint("use bucket on puddle")
    locker_room.add_item(bucket)
    broom = things.Item("broom", "a broom", "A sturdy janitor's broom.")
    broom.add_command_hint("get broom")
    broom.add_command_hint("sweep")
    locker_room.add_item(broom)
    puddle = things.Item(
        "puddle",
        "a puddle of sick on the floor",
        "Yuck. Looks like it was Salisbury steak day. Where's the school janitor when you need him?",
    )
    puddle.set_property("gettable", False)
    puddle.set_property("is_cleaned", False)
    puddle.add_command_hint("examine puddle")
    puddle.add_command_hint("use bucket on puddle")
    puddle.add_use_response(
        tool="bucket",
        response_text="You cover up the slippery puddle. The hallway is now safe.",
        requires_target_properties={"is_cleaned": False},
        sets_target_properties={"is_cleaned": True},
    )
    hallway_west.add_item(puddle)
    door = things.Item(
        "door",
        "a classroom door",
        "You see Mr. Bushel discussing last night's homework. Oops.",
    )
    door.set_property("gettable", False)
    door.add_command_hint("examine door")
